INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quirky Crook', 'A fun little high score game for when you have a few spare minutes. Quirky Crook is a throwback to old arcade games. Try to beat your high score! Go for the highest multiplier you can! Play as a crook, grabbing as many bags of money as you can, all while avoiding the cops on your trail.' FROM games WHERE igdb_id = 81716 ON CONFLICT (game_id, language_code) DO NOTHING;
