INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirate', 'Pirate is a game, that will turn you into young captain Chris Workett, the privateer from England. By happenstance and on the order of Crown he have to complete an important mission for the benefit of England. He is departing to the New World as Crown want him to do… It’s time to fit on the role of captain – recruit best sea dogs, sink your enemies’ ships, fight for the glory of His Majesty and join the history as the Terror of the Seas!' FROM games WHERE igdb_id = 41424 ON CONFLICT (game_id, language_code) DO NOTHING;
