INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossgrams', '"Crossgrams is a new kind of word puzzle which mixes anagrams with crosswords (and has a pinch of Sudoku). It''s simple, challenging, and extremely addictive. To unscramble each puzzle, just drag letters left and right (never up or down), but watch out: it''s not as easy as it seems! Each letter you solve and pin in place is a new clue for the surrounding words. Puzzles range from bite-sized fun to brain-busters you can spend a whole afternoon chipping away at, just like a weekend crossword puzzle."' FROM games WHERE igdb_id = 113250 ON CONFLICT (game_id, language_code) DO NOTHING;
