INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Dead: Virtual Nightmare', 'Evil Dead: Virtual Nightmare is a petrifying first-person endless runner that will immerse you in a frightening world thanks to VR. Roam around the Evil Dead cabin and discover new missions found in the Book of the Dead. Unlock boosts, pick-up new weapons and gather some courage as you frantically race to stay alive! Dare you enter the Evil Dead forest for the ultimate VR horror experience?' FROM games WHERE igdb_id = 106683 ON CONFLICT (game_id, language_code) DO NOTHING;
