INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Link-a-Pix Color', 'Link-a-Pix is a clue-linking puzzle where every grid has a picture hidden inside. The aim is to reveal the picture by painting paths to link the clues. Connect pairs of clues which have the same color and number. The number shows the length of the line which will connect them. Link-a-Pix can always be solved using logic and deduction. You don''t ever have to guess! This game contains 120 exclusive puzzles, designed by Conceptis Ltd. Puzzles range in difficulty and size from small introductory pictures to huge scrollable grids with highly detailed pictures.' FROM games WHERE igdb_id = 85247 ON CONFLICT (game_id, language_code) DO NOTHING;
