INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Hockey', 'Play Air Hockey and re-discover the fun and excitement of this classic arcade game on the big screen, anytime. With stunning 3D graphics, you''ll be transported straight back to the arcades of your youth. Air Hockey takes full advantage of HD graphics, giving you a truly immersive experience of playing on a real table. Play against another player in two player mode or play against the smart artificial intelligent (Ai) player, either way winning won''t come easy.' FROM games WHERE igdb_id = 94114 ON CONFLICT (game_id, language_code) DO NOTHING;
